from pathlib import Path
p=Path('/mnt/data/thqwork/public/index.html')
s=p.read_text()
s=s.replace('<button class="btn primary" id="startWorkout">＋ Log this workout</button><button class="btn ghost" id="editDay">Edit day</button>', '<button class="btn primary" id="startWorkout">＋ Log workout</button><button class="btn" id="startWOD">＋ Log WOD</button><button class="btn ghost" id="editDay">Edit day</button>')
s=s.replace("document.getElementById('startWorkout').onclick=()=>openWorkout(selectedDay);document.getElementById('editDay').onclick", "document.getElementById('startWorkout').onclick=()=>openWorkout(selectedDay);document.getElementById('startWOD').onclick=openWOD;document.getElementById('editDay').onclick")
# Add visible superset button in programming card and handler to same behaviour as swipe
s=s.replace('<span class="muted small">Drag to reorder · swipe left to add superset partner</span></div>', '<span class="muted small">Drag to reorder</span><button type="button" class="btn" data-create-superset style="padding:6px 9px;font-size:11px">＋ Superset</button></div>')
# add event binding after editItems onclick remove handler
old="editItems.onclick=e=>{const b=e.target.closest('[data-remove-item]');if(b)b.closest('.edititem').remove()};let swipeStart=null;"
new="editItems.onclick=e=>{const b=e.target.closest('[data-remove-item]');if(b){b.closest('.edititem').remove();return}const sup=e.target.closest('[data-create-superset]');if(sup){createSupersetPartner(sup.closest('.edititem'),editItems);}};function createSupersetPartner(card,container){if(!card)return;if(card.dataset.supersetGroup){toast('This exercise is already in a superset');return}const group='ss-'+Date.now()+'-'+Math.random().toString(36).slice(2,6);card.dataset.supersetGroup=group;const source={name:'',sets:Number(card.querySelector('[data-k=sets]').value)||3,reps:card.querySelector('[data-k=reps]').value||'10',loadKg:0,loadIncrementKg:0,restTimes:card.querySelector('[data-k=restTimes]').value||'',durationSeconds:0,supersetGroup:group};card.insertAdjacentHTML('afterend',itemEditorHTML(source,container.children.length));const partner=card.nextElementSibling;partner.dataset.supersetGroup=group;partner.querySelector('[data-k=name]').focus();toast('Superset partner added — enter the secondary exercise')}let swipeStart=null;"
s=s.replace(old,new)
# Replace duplicated swipe logic with helper
old="const group='ss-'+Date.now()+'-'+Math.random().toString(36).slice(2,6);card.dataset.supersetGroup=group;const source={name:'',sets:Number(card.querySelector('[data-k=sets]').value)||3,reps:card.querySelector('[data-k=reps]').value||'10',loadKg:0,loadIncrementKg:0,restTimes:card.querySelector('[data-k=restTimes]').value||'',durationSeconds:0,supersetGroup:group};card.insertAdjacentHTML('afterend',itemEditorHTML(source,editItems.children.length));const partner=card.nextElementSibling;partner.dataset.supersetGroup=group;partner.querySelector('[data-k=name]').focus();toast('Superset partner added — enter the secondary exercise')"
s=s.replace(old,"createSupersetPartner(card,editItems)")
# Add WOD modal functions before openWorkout
marker='function openWorkout(day){'
wod=r'''function openWOD(){
 const body=`<div class="formgrid"><div class="field"><label>Date</label><input type="date" id="wodDate" value="${new Date().toISOString().slice(0,10)}"></div><div class="field"><label>WOD name (optional)</label><input id="wodName" placeholder="e.g. Fran, Murph, Daily WOD"></div></div><div class="field"><label>Screenshot / photo of WOD (optional; stored with the log, not automatically read)</label><input id="wodImage" type="file" accept="image/*"><span class="muted small" id="wodImageName">You can also enter the exercises manually below.</span></div><div id="wodRows"></div><button type="button" class="btn" id="wodAddExercise">＋ Add exercise</button><div class="notice">Image recognition is not enabled yet. Attach the WOD image for reference, then enter its exercises, sets, reps and loads below.</div>`;
 modal('Log Workout Of the Day',body,[{label:'Cancel',cls:'btn ghost',action:closeModal},{label:'Save WOD',cls:'btn primary',action:saveWOD}]);
 const rows=document.getElementById('wodRows');const add=()=>{rows.insertAdjacentHTML('beforeend',`<div class="exercise wod-row"><div class="field"><label>Exercise</label><input data-wod="name" placeholder="Movement name"></div><div class="formgrid"><div class="field"><label>Sets</label><input data-wod="sets" type="number" min="1" value="1"></div><div class="field"><label>Reps / time / distance</label><input data-wod="reps" placeholder="e.g. 21-15-9 or 400m"></div><div class="field"><label>Load (kg)</label><input data-wod="weight" type="number" min="0" step="0.5" placeholder="Optional"></div><div class="field"><label>Notes / scaling</label><input data-wod="notes" placeholder="e.g. scaled, banded"></div></div><button type="button" class="btn ghost danger" data-wod-remove>Remove</button></div>`)};
 document.getElementById('wodAddExercise').onclick=add;rows.onclick=e=>{if(e.target.closest('[data-wod-remove]'))e.target.closest('.wod-row').remove()};document.getElementById('wodImage').onchange=e=>{document.getElementById('wodImageName').textContent=e.target.files?.[0]?.name||'No image selected'};add();
}
async function saveWOD(){const rows=[...document.querySelectorAll('#wodRows .wod-row')],items=rows.map(r=>({name:r.querySelector('[data-wod=name]').value.trim(),sets:Math.max(1,Number(r.querySelector('[data-wod=sets]').value)||1),reps:r.querySelector('[data-wod=reps]').value.trim(),weight:Number(r.querySelector('[data-wod=weight]').value)||0,notes:r.querySelector('[data-wod=notes]').value.trim()})).filter(x=>x.name);if(!items.length){toast('Add at least one exercise to the WOD');return}const f=document.getElementById('wodImage')?.files?.[0],photoNote=f?await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f)}):'',date=document.getElementById('wodDate').value||new Date().toISOString().slice(0,10),title=document.getElementById('wodName').value.trim()||'Workout Of the Day';items.forEach((it,i)=>state.logs.push({id:'wod-'+Date.now()+'-'+i,timestamp:new Date(date+'T12:00:00').getTime(),date,day:'WOD',week:activeWeek(),program:active().name,exercise:it.name,weight:it.weight,sets:it.sets,reps:it.reps,notes:[title,it.notes].filter(Boolean).join(' · '),type:'wod',photoNote:i===0?photoNote:'',done:true}));save();closeModal();render();toast('WOD saved: '+items.length+' exercise'+(items.length===1?'':'s'))}
'''
s=s.replace(marker,wod+marker)
# make per-exercise collapse robust for done/undone: CSS hidden content for collapsed, no coupling to completed
s=s.replace('.exercise.exercise-done .exercise-collapsible{display:none}.exercise.exercise-done.is-expanded .exercise-collapsible{display:block}', '.exercise .exercise-collapsible{display:none}.exercise.is-expanded .exercise-collapsible{display:block}')
# change log button label and individual toggle initial states already set; set default expanded if not done
p.write_text(s)
# mirror public index to app.js if app.js is maintained source copy
Path('/mnt/data/thqwork/app.js').write_text(s[s.find('<script>')+8:s.rfind('</script>')] if '<script>' in s else Path('/mnt/data/thqwork/app.js').read_text())
